<?php
require __DIR__.'/../config/config.php'; require __DIR__.'/../includes/functions.php'; require_role('admin');
$errors=[]; $editing=null; $form=['full_name'=>'','email'=>'','student_number'=>''];
if (isset($_GET['edit']) && ctype_digit((string)$_GET['edit'])) { $stmt=$pdo->prepare("SELECT id,full_name,email,student_number FROM users WHERE id=? AND role='student'"); $stmt->execute([(int)$_GET['edit']]); $editing=$stmt->fetch()?:null; if($editing) $form=['full_name'=>$editing['full_name'],'email'=>$editing['email'],'student_number'=>$editing['student_number']]; }
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $action=(string)($_POST['action']??'');
 if($action==='delete') { $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT); if($id && $id>0) { $stmt=$pdo->prepare("DELETE FROM users WHERE id=? AND role='student'"); $stmt->execute([$id]); set_flash('success',$stmt->rowCount()?'Student record deleted.':'Student record was not found.'); } else set_flash('danger','Invalid student record.'); redirect('students.php'); }
 if($action==='save') { $id=filter_var($_POST['id']??'',FILTER_VALIDATE_INT); $id=$id?(int)$id:null; $form['full_name']=trim((string)($_POST['full_name']??'')); $form['email']=trim((string)($_POST['email']??'')); $form['student_number']=trim((string)($_POST['student_number']??''));
  if(mb_strlen($form['full_name'])<2||mb_strlen($form['full_name'])>100) $errors[]='Name must be between 2 and 100 characters.';
  if(!valid_email($form['email'])) $errors[]='Enter a valid email address.';
  if(!valid_student_number($form['student_number'])) $errors[]='Student number must be 3–30 letters, numbers, or hyphens.';
  $dupe=$pdo->prepare('SELECT id FROM users WHERE (email=? OR student_number=?) AND id <> COALESCE(?,0)'); $dupe->execute([$form['email'],$form['student_number'],$id]); if($dupe->fetch()) $errors[]='Email or student number is already used by another account.';
  if($id) { $exists=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='student'"); $exists->execute([$id]); if(!$exists->fetch()) $errors[]='Student record was not found.'; }
  if(!$errors) { if($id) { $stmt=$pdo->prepare("UPDATE users SET full_name=?,email=?,student_number=? WHERE id=? AND role='student'"); $stmt->execute([$form['full_name'],$form['email'],$form['student_number'],$id]); set_flash('success','Student record updated.'); }
   else { $temporaryPassword=bin2hex(random_bytes(8)); $stmt=$pdo->prepare("INSERT INTO users (full_name,email,student_number,password_hash,role) VALUES (?,?,?,?,'student')"); $stmt->execute([$form['full_name'],$form['email'],$form['student_number'],password_hash($temporaryPassword,PASSWORD_DEFAULT)]); set_flash('success','Student record created. Because no email invitation is configured, ask the student to register with a different email/number or add a password-reset flow before production use.'); } redirect('students.php'); }
  $editing=$id?['id'=>$id]:null;
 }
}
$q=trim((string)($_GET['q']??''));
if($q!=='') { $stmt=$pdo->prepare("SELECT id,full_name,email,student_number,created_at FROM users WHERE role='student' AND (full_name LIKE ? OR email LIKE ? OR student_number LIKE ?) ORDER BY created_at DESC"); $term='%'.$q.'%'; $stmt->execute([$term,$term,$term]); $students=$stmt->fetchAll(); }
else $students=$pdo->query("SELECT id,full_name,email,student_number,created_at FROM users WHERE role='student' ORDER BY created_at DESC")->fetchAll();
$pageTitle='Manage students'; $base='../'; require __DIR__.'/../includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><span class="eyebrow">RECORDS</span><h1 class="h2 fw-bold mt-2 mb-1">Student management</h1><p class="text-secondary mb-0">Create, view, update, search, and delete student records.</p></div><span class="role-pill"><?= count($students) ?> result(s)</span></div>
<div class="row g-4"><div class="col-lg-4"><section class="info-card"><h2 class="h5 fw-bold mb-3"><?= $editing?'Edit student':'Add a student' ?></h2><?php foreach($errors as $error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endforeach; ?><form method="post" class="needs-validation" novalidate><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= e(isset($editing['id'])?(string)$editing['id']:'') ?>"><div class="mb-3"><label for="full_name" class="form-label">Full name</label><input class="form-control" id="full_name" name="full_name" value="<?= e($form['full_name']) ?>" maxlength="100" required><div class="invalid-feedback">Enter a name.</div></div><div class="mb-3"><label for="email" class="form-label">Email</label><input class="form-control" id="email" name="email" type="email" value="<?= e($form['email']) ?>" maxlength="190" required><div class="invalid-feedback">Enter a valid email.</div></div><div class="mb-3"><label for="student_number" class="form-label">Student number</label><input class="form-control" id="student_number" name="student_number" value="<?= e($form['student_number']) ?>" pattern="[A-Za-z0-9-]{3,30}" required><div class="invalid-feedback">Use 3–30 letters, numbers, or hyphens.</div></div><button class="btn btn-primary w-100" type="submit"><?= $editing?'Save changes':'Create student' ?></button><?php if($editing): ?><a class="btn btn-link w-100 mt-2" href="students.php">Cancel editing</a><?php endif; ?></form></section></div>
<div class="col-lg-8"><section class="info-card"><form method="get" class="row g-2 mb-3"><div class="col"><label for="q" class="visually-hidden">Search students</label><input class="form-control" id="q" name="q" value="<?= e($q) ?>" placeholder="Search name, email, or student number"></div><div class="col-auto"><button class="btn btn-outline-primary" type="submit">Search</button></div><?php if($q!==''): ?><div class="col-auto"><a class="btn btn-outline-secondary" href="students.php">Clear</a></div><?php endif; ?></form><div class="table-responsive"><table class="table align-middle portal-table"><thead><tr><th>Student</th><th>Student no.</th><th>Created</th><th class="text-end">Actions</th></tr></thead><tbody><?php if(!$students): ?><tr><td colspan="4" class="text-center text-secondary py-4">No student records found.</td></tr><?php endif; ?><?php foreach($students as $student): ?><tr><td><strong><?= e($student['full_name']) ?></strong><div class="small text-secondary"><?= e($student['email']) ?></div></td><td><?= e($student['student_number']) ?></td><td class="small text-secondary"><?= e(date('M j, Y',strtotime($student['created_at']))) ?></td><td><div class="d-flex justify-content-end gap-2"><a class="btn btn-sm btn-outline-primary" href="students.php?edit=<?= (int)$student['id'] ?>">Edit</a><form method="post" class="d-inline delete-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$student['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div></div>
